/** A sailing ship facing right; (x, y) = waterline centre, about 64 wide at s = 1. */
const ship = (x: number, y: number, s = 1, flag: string = RED, crossSail = false, cargo = false) => g(`translate(${x} ${y}) scale(${s})`,
  path('M-32 -12 L-32 -22 L-20 -22 L-20 -12 L28 -12 L34 -18 L30 -12 L24 4 L-26 4 Z', WOOD, C.ink, 1.6), line('M-28 -4 L24 -4', WOOD2, 1.2), ...[-16, -6, 4, 14].map((d) => circle(d, -8, 1.4, WOOD2, null)),
  line('M-6 -12 L-6 -58 M14 -12 L14 -50 M-24 -22 L-24 -44', C.ink, 2),
  path('M-20 -54 Q-6 -48 8 -54 L8 -32 Q-6 -26 -20 -32 Z', SAIL, C.ink, 1.3), path('M2 -46 Q14 -41 26 -46 L26 -26 Q14 -21 2 -26 Z', SAIL, C.ink, 1.3), path('M-24 -42 L-34 -26 L-24 -26 Z', SAIL, C.ink, 1.1),
  crossSail ? all(rect(-7.6, -50, 3.2, 18, RED, 0.5, null), rect(-14, -43, 16, 3.2, RED, 0.5, null)) : '',
  path('M-6 -58 L4 -61 L-6 -64 Z', flag, C.ink, 1), cargo ? all(rect(-16, -20, 8, 8, '#c9a06a', 1, C.ink, 1), rect(-6, -20, 8, 8, '#c9a06a', 1, C.ink, 1), ellipse(6, -16, 4, 4, WOOD2, C.ink, 1)) : '');
/** A small rowing boat; (x, y) = waterline centre. */
const boat = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-18 -6 L18 -6 L13 3 L-13 3 Z', WOOD, C.ink, 1.4), line('M-8 -6 L-16 6 M10 -6 L18 6', WOOD2, 1.6));
/** A church with a tower and a cross; (x, y) = bottom centre. */
