const brush = (x: number, y: number, s = 1, rot = 0, tip = RED) => g(`translate(${x} ${y}) rotate(${rot}) scale(${s})`, rect(-1.2, 0, 2.4, 16, WOOD, 1, C.ink, 0.8), path('M-1.6 0 L1.6 0 L0 -6 Z', tip, C.ink, 0.8));
const palette = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-12 0 C-14 -10 6 -14 12 -6 C14 0 6 0 4 4 C2 8 -10 8 -12 0 Z', '#e6c48a', C.ink, 1.2), circle(-6, -4, 2, RED, null), circle(0, -7, 2, '#3a6ab0', null), circle(6, -5, 2, GOLD, null), circle(-7, 2, 2, GREEN, null));
/** A small classical statue on a plinth; (x, y) = bottom centre. */
const statue = (x: number, y: number, s = 1, col = '#ece6da') => g(`translate(${x} ${y}) scale(${s})`, rect(-10, -10, 20, 10, STONE2, 1, C.ink, 1.2), path('M-6 -10 L-5 -30 L-8 -44 L8 -44 L5 -30 L6 -10 Z', col, C.ink, 1.3), circle(0, -50, 5.5, col, C.ink, 1.3), line('M-8 -42 L-12 -30 M8 -42 L11 -52', col, 3), line('M-8 -42 L-12 -30 M8 -42 L11 -52', C.ink, 0.6));
const gear = (x: number, y: number, r = 8, col = '#8a8f98') => all(...Array.from({ length: 8 }, (_, i) => { const a = (i / 8) * Math.PI * 2; return rect(f1(x + Math.cos(a) * r - 2.4), f1(y + Math.sin(a) * r - 2.4), 4.8, 4.8, col, 0.8, C.ink, 0.8); }), circle(x, y, r, col, C.ink, 1.2), circle(x, y, r * 0.35, C.white, C.ink, 1));
const bag = (x: number, y: number, s = 1, col = '#c9a06a') => g(`translate(${x} ${y}) scale(${s})`, path('M-10 0 C-14 -6 -12 -16 -4 -18 L4 -18 C12 -16 14 -6 10 0 Z', col, C.ink, 1.4), line('M-5 -18 L5 -18', C.ink, 2), circle(0, -8, 3.4, GOLD, C.ink, 0.8));
