const barrel = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-7 0 C-10 -6 -10 -12 -7 -18 L7 -18 C10 -12 10 -6 7 0 Z', WOOD, C.ink, 1.2), line('M-9 -5 L9 -5 M-9 -13 L9 -13', '#5a5f68', 1.2));
const flag = (x: number, y: number, col = RED, h = 30) => all(line(`M${x} ${y} L${x} ${y - h}`, C.ink, 1.8), path(`M${x} ${y - h} L${x + 16} ${y - h + 5} L${x} ${y - h + 10} Z`, col, C.ink, 1.1));
/** A parchment map sheet. */
const mapSheet = (x: number, y: number, w: number, h: number) => all(rect(x, y, w, h, PAPER, 2, C.ink, 1.6), line(`M${x + 2} ${y + 4} L${x + 2} ${y + h - 4} M${x + w - 2} ${y + 4} L${x + w - 2} ${y + h - 4}`, '#d8c494', 1));
const blob = (x: number, y: number, s = 1, col = '#9ccf7a', k = 0) => g(`translate(${x} ${y}) scale(${s})`, path(['M-10 -6 C-6 -14 8 -12 10 -4 C12 4 4 12 -2 10 C-10 8 -14 0 -10 -6 Z', 'M-8 -10 C0 -14 10 -8 8 0 C6 6 8 12 0 12 C-6 10 -12 2 -8 -10 Z', 'M-12 -2 C-10 -10 4 -12 10 -6 C14 0 8 8 0 8 C-8 10 -14 6 -12 -2 Z'][k % 3]!, col, C.ink, 1.2));
const compassRose = (x: number, y: number, r = 9) => all(circle(x, y, r, C.white, C.ink, 1.2), path(`M${x} ${y - r + 1} L${x + 2.4} ${y} L${x} ${y + r - 1} L${x - 2.4} ${y} Z`, RED, C.ink, 0.8), path(`M${x - r + 1} ${y} L${x} ${y - 2} L${x + r - 1} ${y} L${x} ${y + 2} Z`, C.grey, C.ink, 0.6));
/** A globe with continents. */
